   ratified vault. ***
   anchor      : HUB_ASSESSMENT   (kind: hub, origin: data_7.js.parent)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 6 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_ASSESSMENT_HK
   hashdiff    : SAT_ASSESSMENT_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , SUB_STATUS_CODE as ASSESSMENT_SUB_STATUS_CODE
        , SUB_STATUS_DESC as ASSESSMENT_SUB_STATUS_DESCRIPTION
        , APP_TIME as SCHEDULED_TIME
        , RESCHEDULE_DATE as RESCHEDULED_DATE
        , RESCHEDULE_TIME as RESCHEDULED_TIME
        , cast(null as varchar) as INSPECTION_CONDUCTED_INDICATOR
        , 'BA_HCP_PP_MEM_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_pp_mem_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
),

resolved as (
    select
        HUB_ASSESSMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_SUB_STATUS_CODE end) as ASSESSMENT_SUB_STATUS_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_SUB_STATUS_DESCRIPTION end) as ASSESSMENT_SUB_STATUS_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SCHEDULED_TIME end) as SCHEDULED_TIME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RESCHEDULED_DATE end) as RESCHEDULED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RESCHEDULED_TIME end) as RESCHEDULED_TIME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSPECTION_CONDUCTED_INDICATOR end) as INSPECTION_CONDUCTED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ASSESSMENT_HK
),

hashed as (
    select
        *,
        case when ASSESSMENT_SUB_STATUS_CODE is not null or ASSESSMENT_SUB_STATUS_DESCRIPTION is not null or SCHEDULED_TIME is not null or RESCHEDULED_DATE is not null or RESCHEDULED_TIME is not null or INSPECTION_CONDUCTED_INDICATOR is not null
                     then md5(upper(coalesce(cast(ASSESSMENT_SUB_STATUS_CODE as varchar), '') || '|' || coalesce(cast(ASSESSMENT_SUB_STATUS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(SCHEDULED_TIME as varchar), '') || '|' || coalesce(cast(RESCHEDULED_DATE as varchar), '') || '|' || coalesce(cast(RESCHEDULED_TIME as varchar), '') || '|' || coalesce(cast(INSPECTION_CONDUCTED_INDICATOR as varchar), '')))
                end as SAT_ASSESSMENT_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ASSESSMENT_HK is not null
  and SAT_ASSESSMENT_HEADER_HASHDIFF is not null
